-- 011 — programação da edição (roadmap 037 Onda 1 #4, research 035 #5).
-- "Que horas é o almoço / em que sala é a oficina" é a primeira pergunta no
-- grupo do zap. Item tem início/fim (TEXT UTC como o resto do projeto;
-- exibição em America/Sao_Paulo), sala, público e tipo. Rascunho até
-- publicar (publishedAt); mudar horário/sala de item publicado gera aviso.

CREATE TABLE schedule_items (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id") ON DELETE CASCADE,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "startsAt" TEXT NOT NULL,
  "endsAt" TEXT NOT NULL,
  "room" TEXT NOT NULL DEFAULT '',
  "audience" TEXT NOT NULL DEFAULT 'todos'
    CHECK ("audience" IN ('todos','participantes','mentores','jurados','staff')),
  "kind" TEXT NOT NULL DEFAULT 'outro'
    CHECK ("kind" IN ('abertura','palestra','oficina','refeicao','mentoria','pitch','encerramento','outro')),
  "publishedAt" TEXT,
  -- sobe a cada mudança de horário/sala; (itemId, revision) é a chave de
  -- idempotência do aviso automático e o SEQUENCE do .ics
  "revision" INTEGER NOT NULL DEFAULT 0,
  "createdBy" INTEGER REFERENCES members("id") ON DELETE SET NULL,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "updatedAt" TEXT NOT NULL DEFAULT sqlite_now(),
  -- formato fixo YYYY-MM-DD HH:MM:SS → comparação de texto = cronológica
  CHECK ("endsAt" > "startsAt")
);
CREATE INDEX idx_schedule_items_hackathon ON schedule_items ("hackathonId", "startsAt");

-- uma linha por alteração avisada: refazer a mesma alteração (retry, clique
-- duplo, dois organizadores ao mesmo tempo) não duplica o aviso
CREATE TABLE schedule_change_notices (
  "itemId" INTEGER NOT NULL REFERENCES schedule_items("id") ON DELETE CASCADE,
  "revision" INTEGER NOT NULL,
  "announcementId" INTEGER REFERENCES announcements("id") ON DELETE SET NULL,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  PRIMARY KEY ("itemId", "revision")
);

-- feed .ics pessoal (sem login, link assinado). version entra na assinatura:
-- revogar = version + 1, e todo link antigo para de valer na hora.
CREATE TABLE calendar_feeds (
  "memberId" INTEGER NOT NULL REFERENCES members("id") ON DELETE CASCADE,
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id") ON DELETE CASCADE,
  "version" INTEGER NOT NULL DEFAULT 1,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "rotatedAt" TEXT,
  PRIMARY KEY ("memberId", "hackathonId")
);

-- aviso com lista explícita de destinatários (o fan-out já nasce pronto):
-- é como a programação avisa só mentores/jurados/staff/participantes de um
-- item, públicos que não existem em announcements.
ALTER TABLE announcements DROP CONSTRAINT announcements_audience_check;
ALTER TABLE announcements ADD CONSTRAINT announcements_audience_check
  CHECK ("audience" IN ('todos','aprovados','presentes','time','lista'));
